<?php
declare(strict_types=1);
$referrals = $marketingStore->referralDefinitions(); $editing = null;
foreach ($referrals as $referral) if (($_GET['edit_referral'] ?? null) === $referral['id']) $editing = $referral;
$couponAssignments = $marketingStore->couponAttribution(); $coupons = app_store()->coupons(false);
mm_measurement_authorize();
?>
<div class="marketing-admin-grid"><section class="marketing-card"><h2><?= $editing === null ? 'New referral code' : 'Edit referral code' ?></h2><form class="marketing-form" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_referral"><input type="hidden" name="id" value="<?= velvet_marketing_escape($editing['id'] ?? '') ?>"><input type="hidden" name="referral_revision" value="<?= velvet_marketing_escape($editing['revision'] ?? '') ?>"><label>Code<input name="code" maxlength="64" pattern="[A-Za-z0-9][A-Za-z0-9_-]{0,63}" value="<?= velvet_marketing_escape($editing['code'] ?? '') ?>" <?= $editing !== null ? 'readonly' : '' ?> required></label><label>Label<input name="label" maxlength="120" value="<?= velvet_marketing_escape($editing['label'] ?? '') ?>"></label><label class="marketing-check"><input type="checkbox" name="enabled" value="1" <?= $editing === null || $editing['enabled'] ? 'checked' : '' ?> style="width:auto"> Accept new referral visits</label><p>Only enabled, unique saved codes qualify. Visitors must allow measurement. Registration and checkout retain the verified origin; disabling a code stops new attribution.</p><button class="marketing-button">Save Referral</button></form></section>
<section class="marketing-card"><h2>Saved referral codes</h2><?php foreach ($referrals as $referral): ?><p><code>?ref=<?= velvet_marketing_escape($referral['code']) ?></code> — <?= velvet_marketing_escape($referral['label']) ?> · <?= $referral['enabled'] ? 'Enabled' : 'Disabled' ?> <a href="?page=marketing&amp;tab=referrals&amp;edit_referral=<?= rawurlencode($referral['id']) ?>">Edit</a></p><?php endforeach; ?></section></div>
<section class="marketing-card" style="margin-top:22px" data-coupon-attribution><h2>Coupon campaign attribution</h2><p>Connect an existing checkout coupon to a campaign. For visitors who allow measurement, a valid applied coupon takes precedence over the last campaign click. Referral origin is retained. Previous orders keep their immutable attribution.</p><form class="marketing-form" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_coupon_attribution"><input type="hidden" name="coupon_revision" value="<?= velvet_marketing_escape($couponAssignments['revision']) ?>"><label>Saved coupon<select name="coupon_code" aria-label="Saved coupon" required><option value="">Choose a coupon</option><?php foreach ($coupons as $coupon): ?><option value="<?= velvet_marketing_escape((string) $coupon['code']) ?>"><?= velvet_marketing_escape((string) $coupon['code']) ?></option><?php endforeach; ?></select></label><label>Saved campaign<select name="campaign_id" aria-label="Saved campaign" required><option value="">Choose a campaign</option><?php foreach ($data['campaigns'] as $campaign): ?><option value="<?= velvet_marketing_escape((string) $campaign['id']) ?>"><?= velvet_marketing_escape((string) ($campaign['subject'] ?? $campaign['name'] ?? 'Saved campaign')) ?></option><?php endforeach; ?></select></label><label class="marketing-check"><input type="checkbox" name="enabled" value="1" checked style="width:auto"> Enable this assignment for future checkout</label><button class="marketing-button">Save coupon attribution</button></form><ul><?php foreach ($couponAssignments['assignments'] as $code => $assignment): ?><li><?= velvet_marketing_escape((string) $code) ?> → <?= velvet_marketing_escape(is_string($assignment['campaign_id'] ?? null) ? $assignment['campaign_id'] : 'Needs review') ?> (<?= ($assignment['enabled'] ?? false) === true ? 'enabled' : 'disabled' ?>)</li><?php endforeach; ?></ul></section>
